SELECT sc.nSCId,sc.dDate,sc.vLocation,scd.nId,sjd.vNumber as vTktNumber,sjd.vType,sjd.nCredit, CASE WHEN ca.vBalAmt > 0 THEN (sjd.nCredit - (CASE WHEN (SELECT SUM(vAllAmt) FROM {PRE}CashAllocation WHERE nSalesCloseId = sc.nSCId AND nSalesCloseDetId = scd.nId AND nDrAccount = '1' AND vTable = 'V') is null THEN 0 ELSE (SELECT SUM(vAllAmt) FROM {PRE}CashAllocation WHERE nSalesCloseId = sc.nSCId AND nSalesCloseDetId = scd.nId AND nDrAccount = '1' AND vTable = 'V') END)) ELSE sjd.nCredit END AS allocAmt , CASE WHEN sjd.nCredit - (CASE WHEN (SELECT SUM(vAllAmt) FROM {PRE}CashAllocation WHERE nSalesCloseId = sc.nSCId AND nSalesCloseDetId = scd.nId AND nDrAccount = '1' AND vTable = 'V') is null THEN 0 ELSE (SELECT SUM(vAllAmt) FROM {PRE}CashAllocation WHERE nSalesCloseId = sc.nSCId AND nSalesCloseDetId = scd.nId AND nDrAccount = '1' AND vTable = 'V') END) > 0 THEN 1 ELSE 0 END AS balCheck FROM {PRE}SalesClosing sc LEFT JOIN {PRE}SalesClosingDetails scd ON sc.nSCId = scd.nSalesCloseId LEFT JOIN {PRE}SalesAccountDetails sad ON sc.nSCId = sad.nSalesCloseId LEFT JOIN {PRE}SystemJvDetails sjd ON (sjd.vType=scd.vType AND sjd.vNumber=scd.vTktNumber) LEFT JOIN {PRE}TicketFareDetails tfd ON sjd.vNumber = tfd.nTicketId LEFT JOIN {PRE}CashAllocation ca ON (ca.nSalesCloseId = sc.nSCId AND scd.nId = ca.nSalesCloseDetId) WHERE sjd.nAccHeadId = '32' AND sjd.nAGId = '18' AND tfd.nAcc='1' AND sjd.nCredit != 0 GROUP BY sjd.nSjDId HAVING (balCheck > 0 OR scd.nId NOT IN(SELECT nSalesCloseDetId FROM {PRE}CashAllocation)) ORDER BY sc.dDate DESC
